# Generated by test-lab — blind adversarial evaluation
"""Regression tests for the convert-autogrid /sprite-atlas lane.

Live proof of the real path is a full raw ChatGPT sheet -> validated 512x896
atlas (done manually). These tests lock the three pieces of logic that make the
lane robust to AI-generated sheets:
  * row-band detection (drifting, non-uniform rows),
  * main-subject isolation (drops neighbour-frame edge slivers, keeps VFX),
  * background-kind detection + end-to-end hold-last-frame fill.
"""
from __future__ import annotations

import importlib.util
from pathlib import Path

import numpy as np
from PIL import Image

_UTIL = Path(__file__).resolve().parent.parent / "utils" / "clean_sprite_atlas.py"
_spec = importlib.util.spec_from_file_location("clean_sprite_atlas", _UTIL)
csa = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(csa)


def test_detect_row_bands_handles_drifting_rows() -> None:
    """14 bands whose pitch drifts (as generators produce) are all detected."""
    height, width = 1900, 640
    mask = np.zeros((height, width), dtype=bool)
    y = 20
    for row in range(14):
        mask[y : y + 60, 100:540] = True  # a content band
        y += 90 + 4 * row  # growing pitch => drift
    bands = csa._detect_row_bands(mask)
    assert len(bands) == 14, f"expected 14 drifting bands, got {len(bands)}"
    # bands are ordered, non-overlapping, and each has real height
    for (s, e), (ns, _ne) in zip(bands, bands[1:]):
        assert s < e < ns


def test_isolate_main_subject_drops_edge_sliver_keeps_body() -> None:
    cell = np.zeros((90, 64, 4), dtype=np.uint8)
    # main body: solid block near centre
    cell[20:80, 18:46, :] = (120, 60, 160, 255)
    # neighbour bleed: thin 3px opaque strip hugging the right edge
    cell[10:80, 61:64, :] = (200, 40, 40, 255)
    out = np.array(csa._isolate_main_subject(Image.fromarray(cell, "RGBA")))
    assert out[40, 30, 3] > 0, "main body must survive"
    assert out[40, 62, 3] == 0, "right-edge sliver must be removed"


def test_isolate_main_subject_keeps_large_edge_vfx() -> None:
    cell = np.zeros((90, 64, 4), dtype=np.uint8)
    cell[20:80, 8:40, :] = (120, 60, 160, 255)  # body
    # a big projectile blob touching the right edge (legit VFX, not a sliver)
    cell[30:70, 44:64, :] = (60, 200, 60, 255)
    out = np.array(csa._isolate_main_subject(Image.fromarray(cell, "RGBA")))
    assert out[50, 55, 3] > 0, "large edge VFX must be preserved"


def test_detect_background_kind() -> None:
    trans = np.zeros((20, 20, 4), dtype=np.uint8)
    assert csa._detect_background_kind(Image.fromarray(trans, "RGBA")) == "transparent"
    dark = np.zeros((20, 20, 3), dtype=np.uint8)
    assert csa._detect_background_kind(Image.fromarray(dark, "RGB")) == "dark"
    light = np.full((20, 20, 3), 230, dtype=np.uint8)
    assert csa._detect_background_kind(Image.fromarray(light, "RGB")) == "checker"


def _synthetic_checkerboard_sheet(missing_last_row: int) -> Image.Image:
    """A 14-row checkerboard sheet with drift; `missing_last_row` omits its final frame."""
    cols, cell = 8, 100
    width, height = cols * cell, 14 * cell
    base = np.full((height, width, 3), 235, dtype=np.uint8)
    base[::20, :, :] = 210  # faint checker texture (still light + low-sat)
    y = 6
    for row, (_name, count) in enumerate(csa.ROWS):
        draw = count - 1 if row == missing_last_row else count
        for col in range(draw):
            cx, cy = col * cell + 20, y + 10
            base[cy : cy + 60, cx : cx + 60, :] = (110, 50, 150)  # saturated blob
        y += cell + row  # drift
    return Image.fromarray(base[:height], "RGB")


def test_convert_autogrid_end_to_end(tmp_path: Path) -> None:
    src = tmp_path / "sheet.png"
    _synthetic_checkerboard_sheet(missing_last_row=8).save(src)
    out_png = tmp_path / "out.png"
    out_json = tmp_path / "out.json"
    csa.convert_autogrid(
        source=src, sprite_id="unit_probe", out_png=out_png, out_json=out_json,
        frame_width=64, frame_height=64, columns=8, background="auto",
        background_lower=200, background_upper=255, neutral_spread=42,
        row_pad=6, gutter=2, hold_last_frame=True,
    )
    im = Image.open(out_png).convert("RGBA")
    assert im.size == (512, 896)
    a = np.array(im)
    assert int(a[0, 0, 3]) == 0, "corner must be transparent"
    # hold-last-frame: the row that was missing its final frame is fully populated
    total = sum(c for _n, c in csa.ROWS)
    filled = 0
    y = 0
    for _row, (_name, count) in enumerate(csa.ROWS):
        for col in range(count):
            if (a[y : y + 64, col * 64 : col * 64 + 64, 3] > 16).any():
                filled += 1
        y += 64
    assert filled == total, f"hold-last-frame should fill every canonical cell: {filled}/{total}"
